<?php $money = fn($x) => number_format((float)$x, 2); ?>
<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h5 mb-0">رسوم <?= e($s['student']['full_name']) ?></h2><a class="btn btn-outline-secondary ms-auto" href="<?= url('portal/student/' . (int)$studentId) ?>"><i class="bi bi-arrow-right"></i> رجوع</a></div>
<?php if (!$s['fees']): ?><div class="card-s empty-state"><i class="bi bi-receipt"></i>لا توجد رسوم معيَّنة حاليًا.</div><?php endif; ?>
<div class="row g-3 mb-3"><?php foreach ($s['totals'] as $c => $t): ?><div class="col-12 col-md-6"><div class="card-s"><div class="small text-muted">الإجمالي (<?= e($c) ?>)</div><div class="d-flex justify-content-between"><span>المستحق <strong><?= $money($t['payable']) ?></strong></span><span class="text-success">المدفوع <strong><?= $money($t['paid']) ?></strong></span><span class="<?= (float)$t['balance'] > 0 ? 'text-danger' : 'text-success' ?>">المتبقي <strong><?= $money($t['balance']) ?></strong></span></div></div></div><?php endforeach; ?></div>
<?php foreach ($s['fees'] as $f): ?><div class="card-s mb-3"><h3 class="h6"><?= e($f['structure_name']) ?> <small class="text-muted"><?= e($f['year_name']) ?></small></h3>
  <div class="table-responsive"><table class="table table-sm align-middle table-cards mb-2"><thead><tr><th>القسط</th><th>الاستحقاق</th><th>القيمة</th><th>المسدَّد</th><th>الحالة</th></tr></thead><tbody>
  <?php foreach ($f['installments'] as $i): $late = $i['status'] !== 'paid' && $i['due_date'] < date('Y-m-d'); ?><tr class="<?= $late ? 'table-danger' : '' ?>"><td data-label="القسط"><?= (int)$i['seq'] ?></td><td data-label="الاستحقاق" dir="ltr"><?= e($i['due_date']) ?></td><td data-label="القيمة"><?= $money($i['amount']) ?> <?= e($f['currency']) ?></td><td data-label="المسدَّد"><?= $money($i['paid_amount']) ?></td><td data-label="الحالة"><?= $i['status'] === 'paid' ? 'مسدّد' : ($late ? 'متأخر' : ($i['status'] === 'partial' ? 'جزئي' : 'مستحق')) ?></td></tr><?php endforeach; ?></tbody></table></div>
  <?php foreach ($f['payments'] as $p): if ($p['voided_at']) continue; ?><div class="d-flex justify-content-between border-top py-1 small"><span dir="ltr"><?= e($p['paid_on']) ?></span><span><?= $money($p['amount']) ?> <?= e($p['currency']) ?> — <?= e($p['method']) ?></span><a target="_blank" href="<?= url('portal/receipts/' . (int)$p['receipt_id'] . '/print') ?>"><i class="bi bi-printer"></i> <?= e($p['receipt_no']) ?></a></div><?php endforeach; ?></div><?php endforeach; ?>
<?php foreach ($s['fees'] as $f): if (empty($pay[(int)$f['id']])): continue; endif; ?>
<div class="card-s mb-3 d-flex flex-wrap align-items-center gap-2"><div class="flex-grow-1"><strong><?= e($f['structure_name']) ?></strong> <span class="text-muted small">— المتبقي <?= number_format((float)$f['balance'], 2) ?> <?= e($f['currency']) ?></span></div><a class="btn btn-success" href="<?= url('portal/pay/' . (int)$f['id']) ?>"><i class="bi bi-credit-card"></i> سداد الرسوم</a></div>
<?php endforeach; ?>
<p class="small text-muted"><?= empty($pay) ? 'للسداد تواصل مع إدارة المدرسة.' : 'بعد الدفع يظهر السند هنا فور تأكيد المزود.' ?> يُحدَّث الكشف فور تسجيل الدفعة.</p>
